-        <a href="#activity">Activity</a>
+        {destinations.map(({ href, label }) => (
+          <a
+            key={href}
+            href={href}
+            aria-current={activeHash === href ? 'page' : undefined}
+            onClick={() => {
+              setActiveHash(href);
+              setOpen(false);
+            }}
